-- United States History 1 final module. Run seed_ushistory1_course.sql first. Safe to run more than once.

do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'united-states-history-1';
  if cid is null then raise exception 'Run the course file first'; end if;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 7, $j$Final Assessment: Turning Point Research Project$j$, $j${"prompt": "Complete a research project on one turning point in American history from this course. Choose from: the Emancipation Proclamation, the end of Reconstruction, the Homestead Act, the Pullman Strike, the Nineteenth Amendment, the Spanish American War, the Great Depression and the New Deal, Pearl Harbor, Brown v. Board of Education or the fall of the Berlin Wall. Write complete sentences and label each part. Proverbs 25:2 says, It is the glory of God to conceal a thing: but the honour of kings is to search out a matter.\n\nPart 1: Question and Timeline. State a clear historical question about your turning point. Make a timeline of at least eight dates that show the causes and effects.\nPart 2: Sources. Identify at least one primary source and one secondary source about your topic (a sample is acceptable if you cannot find a real one, and you must say it is a sample). Tell who made each, when, why, and what each leaves out.\nPart 3: Causes. Explain at least two long term causes and one immediate trigger.\nPart 4: Effects. Explain at least three effects on government, the economy, rights or daily life.\nPart 5: Competing Interpretations. Describe how two historians or viewpoints might disagree about your turning point and tell which argument you find stronger and why.\nPart 6: Connections. Tell how the turning point still shapes the nation, your community or your own faith today, and connect it to another unit in this course.\nPart 7: Reflection. In at least 100 words, explain what this course taught you about God's rule over nations, honest use of evidence, and how to treat people of every race and nation with dignity. Use Proverbs 14:34, which says, Righteousness exalteth a nation: but sin is a reproach to any people.", "rubric": "200 points. Part 1, question and timeline: 24 points. Part 2, sources: 30 points. Part 3, causes: 28 points. Part 4, effects: 30 points. Part 5, competing interpretations: 32 points. Part 6, connections: 28 points. Part 7, reflection: 20 points. Clear organization and complete sentences: 8 points. A score of 140 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Final Assessment: Turning Point Research Project$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 31, $j$Final Exam: United States History 1$j$, $j${"questions": [{"q": "The Thirteenth Amendment:", "options": ["Abolished slavery", "Gave women the vote", "Created income tax", "Ended Prohibition"]}, {"q": "The Fourteenth Amendment guaranteed:", "options": ["A federal income tax", "Citizenship and equal protection", "Direct election of senators", "The eighteen year old vote"]}, {"q": "Andrew Carnegie is associated with:", "options": ["Oil", "Railroads only", "Radio", "Steel"]}, {"q": "Ellis Island served immigrants arriving in:", "options": ["San Francisco", "Boston", "Miami", "New York"]}, {"q": "Muckrakers were:", "options": ["Generals", "Union organizers", "Railroad owners", "Writers who exposed wrongs"]}, {"q": "The Nineteenth Amendment gave:", "options": ["Women the right to vote", "A draft", "Freedom to slaves", "A national income tax"]}, {"q": "The Spanish American War resulted in American control of:", "options": ["Canada", "Texas and California", "Alaska and Hawaii only", "The Philippines, Guam and Puerto Rico"]}, {"q": "The Zimmermann Telegram urged:", "options": ["Britain to surrender", "Mexico to join Germany", "Japan to attack", "Russia to quit"]}, {"q": "The cause of the stock market crash of 1929 included:", "options": ["A drought only", "The Panama Canal", "Buying on margin and overspeculation", "A foreign invasion"]}, {"q": "Which New Deal agency insured bank deposits?", "options": ["FDIC", "WPA", "CCC", "TVA"]}, {"q": "The attack on Pearl Harbor occurred in:", "options": ["1917", "1929", "1941", "1950"]}, {"q": "D Day was the Allied invasion of:", "options": ["Tokyo", "Rome", "Berlin", "Normandy"]}, {"q": "Executive Order 9066 led to:", "options": ["Internment of Japanese Americans", "Rationing", "The draft", "D Day"]}, {"q": "The Supreme Court decision that ruled separate schools unequal was:", "options": ["Marbury v. Madison", "Korematsu v. United States", "Plessy v. Ferguson", "Brown v. Board of Education"]}, {"q": "The Cold War ended with the:", "options": ["Great Depression", "Treaty of Paris", "Fall of the Berlin Wall and the end of the Soviet Union", "Attack on Pearl Harbor"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: United States History 1$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,3,3,3,0,3,1,2,0,2,3,0,3,2}'::int[], array[$j$It was ratified in 1865.$j$,$j$It was added during Reconstruction.$j$,$j$He later gave away much of his fortune.$j$,$j$It opened in 1892.$j$,$j$Their work led to reforms.$j$,$j$It was ratified in 1920.$j$,$j$The Treaty of Paris ended the war.$j$,$j$It helped bring America into World War I.$j$,$j$Borrowing made the collapse worse.$j$,$j$It restored trust in banks.$j$,$j$Congress declared war on Japan the next day.$j$,$j$It began June 6, 1944.$j$,$j$It is remembered as a grave injustice.$j$,$j$It was decided in 1954.$j$,$j$Those events came in 1989 and 1991.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: United States History 1$j$ on conflict (item_id) do nothing;
end
$seed$;
